/*
 * A304811  Solution (a(n)) of the complementary equation a(n) = b(2n) + b(5n)
 *          ; see Comments.
 * https://oeis.org/A304811
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = b(2n) + b(5n); b(n) = least new (smallest unused positive
 *            integer)
 * Range:     u8 n <= 31, u16 n <= 8191, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 1118, big any n
 * Helpers:   used_test
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  The sequence is generated by building b(n) sequentially and assigning a(n) whenever the
    required b-values are available.  The implementation keeps track of all values that
    have been used (both a and b) in a dynamic bit‑set to determine the next "least new". */

#include <stdlib.h>
#include <stdint.h>
#include "../utils/used_test.h"

/* ----------------------------------------------------- */
/*   dynamic bit‑set utilities for tracking used numbers */
static void ensure_used_capacity(idx_t v, uint64_t **used, idx_t *cap)
{
    idx_t word = v >> 6;                 /* each word holds 64 bits   */
    if (word < *cap)
        return;
    idx_t new_cap = (*cap) ? (*cap) << 1 : 16;
    while (new_cap <= word)
        new_cap <<= 1;
    *used = (uint64_t *)realloc(*used, new_cap * sizeof(uint64_t));
    /* zero any newly allocated words */
    for (idx_t i = *cap; i < new_cap; ++i)
        (*used)[i] = 0;
    *cap = new_cap;
}

static inline void used_set(idx_t v, uint64_t **used, idx_t *cap)
{
    ensure_used_capacity(v, used, cap);
    (*used)[v >> 6] |= ((uint64_t)1) << (v & 63);
}

/* ----------------------------------------------------- */

seq_t a(idx_t n)
{
    /* static state -------------------------------------------------------- */
    static idx_t      b_len   = 0;   /* number of b entries already computed   */
    static idx_t      b_cap   = 0;   /* capacity of b array                    */
    static seq_t     *b       = NULL;/* b array: b[i] is the i‑th element       */

    static idx_t      a_cap   = 0;   /* capacity of a array                    */
    static seq_t     *a_arr   = NULL;/* a array: a_arr[i] is the i‑th element  */

    static uint64_t  *used    = NULL;/* bit‑set of all values already used      */
    static idx_t      used_cap= 0;    /* number of 64‑bit words in 'used'       */

    static idx_t      next_unused = 1;/* smallest positive integer not yet used*/

    /* We must have at least indices 0 .. 5*n, because a(n) involves b(5n). */
    idx_t need_b_len = 5 * n + 1;   /* inclusive of index 5*n */

    /* Grow b array if necessary */
    if (b_cap < need_b_len) {
        idx_t new_cap = b_cap ? b_cap << 1 : 16;
        while (new_cap < need_b_len)
            new_cap <<= 1;
        b = (seq_t *)realloc(b, new_cap * sizeof(seq_t));
        b_cap = new_cap;
    }

    /* Grow a array if necessary */
    if (a_cap < need_b_len) {
        idx_t new_cap = a_cap ? a_cap << 1 : 16;
        while (new_cap < need_b_len)
            new_cap <<= 1;
        a_arr = (seq_t *)realloc(a_arr, new_cap * sizeof(seq_t));
        a_cap = new_cap;
    }

    /* Allocate used bit‑set on first call */
    if (!used) {
        used_cap = 16;
        used = (uint64_t *)calloc(used_cap, sizeof(uint64_t));
    }

    /* Main generation loop ------------------------------------------------ */
    while (b_len < need_b_len) {
        /* a. pick the next unused integer as the new b-value */
        seq_t val = (seq_t)next_unused;
        b[b_len]   = val;
        used_set((idx_t)val, &used, &used_cap);

        /* advance next_unused to the next integer that is not yet used */
        do {
            ++next_unused;
        } while (used_test((idx_t)next_unused, used, used_cap));

        /* b. indices of the element just added */
        idx_t cur = b_len;
        ++b_len;

        /* c. try to compute a[cur/2] if cur is divisible by 2 */
        if ((cur & 1) == 0) {
            idx_t k = cur >> 1;                /* k = cur/2 */
            if ((5 * k) <= cur && a_arr[k] == 0) {
                seq_t an = b[2 * k] + b[5 * k];
                a_arr[k] = an;
                used_set((idx_t)an, &used, &used_cap);
                if ((idx_t)an == next_unused) {
                    do {
                        ++next_unused;
                    } while (used_test((idx_t)next_unused, used, used_cap));
                }
            }
        }

        /* d. try to compute a[cur/5] if cur is divisible by 5 */
        if ((cur % 5) == 0) {
            idx_t k = cur / 5;                  /* k = cur/5 */
            if ((2 * k) <= cur && a_arr[k] == 0) {
                seq_t an = b[2 * k] + b[5 * k];
                a_arr[k] = an;
                used_set((idx_t)an, &used, &used_cap);
                if ((idx_t)an == next_unused) {
                    do {
                        ++next_unused;
                    } while (used_test((idx_t)next_unused, used, used_cap));
                }
            }
        }
    }

    /* Return requested term */
    return a_arr[n];
}
